-- Two comments per request, the first at creation and the second at last activity.
INSERT INTO comments (request_id, author_id, body, public, created_at, updated_at)
SELECT r.id, r.requester_id, 'Comment body', random() < 0.9, r.created_at, r.created_at
FROM requests r;
INSERT INTO comments (request_id, author_id, body, public, created_at, updated_at)
SELECT r.id, r.requester_id, 'Follow-up', random() < 0.9, r.updated_at, r.updated_at
FROM requests r;
-- One busy request with 5000 comments, for deep comment paging.
INSERT INTO comments (request_id, author_id, body, public, created_at, updated_at)
SELECT 1, 1, 'Busy ' || i, true, now() - ((5000 - i) * interval '1 minute'), now() FROM generate_series(1, 5000) i;

INSERT INTO groups (account_id, name, created_at, updated_at)
SELECT 1, 'Group ' || i, now(), now() FROM generate_series(1, 20) i;
INSERT INTO group_memberships (group_id, user_id, "default", created_at, updated_at)
SELECT g.id, u.id, (row_number() OVER ()) = 1, now(), now()
FROM groups g JOIN users u ON u.account_id = 1 AND u.role <> 'customer' AND u.id % 20 = g.id % 20 WHERE g.account_id = 1;
INSERT INTO invitations (account_id, invited_by_id, email, role, token_digest, expires_at, created_at, updated_at)
SELECT 1, 1, 'invitee' || i || '@x.test', 'agent', 'digest' || i, now() + interval '7 days', now(), now()
FROM generate_series(1, 20000) i;
ANALYZE;
EOF
time psql "$BENCH_URL" -q -f /tmp/repro/seed2.sql 2>&1 | tail -3; psql "$BENCH_URL" -c "select count(*) comments from comments" -c "select count(*) groups from groups" -c "select count(*) memberships from group_memberships" -c "select count(*) invitations from invitations"

